from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    sep = counts.most_common(1)[0][0]
    fill = Counter(v for v in counts if v != sep)
    fill_color = fill.most_common(1)[0][0]

    line_rows = [r for r in range(h) if grid[r].count(sep) >= w * 0.5]
    marker_cols = sorted({
        c for r in line_rows
        for c in range(w)
        if grid[r][c] != sep and grid[r][c] != fill_color
    })

    out = []
    for r1, r2 in zip(line_rows, line_rows[1:]):
        row = []
        for c1, c2 in zip(marker_cols, marker_cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            if corners[0] not in (sep, fill_color) and len(set(corners)) == 1:
                row.append(corners[0])
            else:
                row.append(fill_color)
        out.append(row)
    return out
